function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  // Standar kualitas: Tanpa efek glow, bloom, atau artificial light
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';

  const minSide = Math.min(width, height);
  const s = minSide / 1080; // Skala proporsional 4K / 2K / FHD

  // Interpolasi transisi seamless antar-scene (0 = Grid Rapat, 1 = Screen Share Dashboard)
  let morph = 0;
  if (currentScene === 0) {
    if (sceneProgress < 0.82) {
      morph = 0;
    } else {
      const p = (sceneProgress - 0.82) / 0.18;
      morph = p * p * (3 - 2 * p);
    }
  } else {
    if (sceneProgress < 0.82) {
      morph = 1;
    } else {
      const p = (sceneProgress - 0.82) / 0.18;
      morph = 1 - (p * p * (3 - 2 * p));
    }
  }

  // Palet Warna UI Korporat Dark-Mode Netral
  const cBgCard = '#111827';
  const cBgCardAlt = '#141D30';
  const cBorder = '#1F293D';
  const cBorderHighlight = '#334155';
  const cAccentBlue = '#2563EB';
  const cAccentCyan = '#0284C7';
  const cAccentGreen = '#10B981';
  const cAccentAmber = '#D97706';
  const cTextPrimary = '#F8FAFC';
  const cTextSecondary = '#94A3B8';
  const cTextMuted = '#64748B';

  // 1. Latar Belakang Kanvas
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#070B14');
  bgGrad.addColorStop(1, '#0C1220');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // Grid Latar Belakang Tipis & Presisi
  ctx.save();
  ctx.strokeStyle = '#111A2E';
  ctx.lineWidth = Math.max(1, 1 * s);
  const gridStep = 48 * s;
  ctx.beginPath();
  for (let x = 0; x < width; x += gridStep) {
    ctx.moveTo(x, 0);
    ctx.lineTo(x, height);
  }
  for (let y = 0; y < height; y += gridStep) {
    ctx.moveTo(0, y);
    ctx.lineTo(width, y);
  }
  ctx.stroke();
  ctx.restore();

  // Helper Fungsi: Rounded Rectangle Vektor
  function drawRoundedRect(x, y, w, h, r, fill, stroke, strokeColor, strokeWidth) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
    if (fill) {
      ctx.fillStyle = fill;
      ctx.fill();
    }
    if (stroke) {
      ctx.strokeStyle = strokeColor || cBorder;
      ctx.lineWidth = strokeWidth || Math.max(1, 1.2 * s);
      ctx.stroke();
    }
  }

  // Pengaturan Layout & Margin
  const marginX = 40 * s;
  const headerY = 24 * s;
  const headerH = 56 * s;
  const footerH = 68 * s;
  const footerY = height - footerH - 24 * s;
  const mainY = headerY + headerH + 16 * s;
  const mainH = footerY - mainY - 16 * s;
  const mainW = width - marginX * 2;

  // 2. Bar Status Header Atas
  drawRoundedRect(marginX, headerY, mainW, headerH, 10 * s, '#0E1626', true, cBorder, 1 * s);

  // Indikator Titik Status Sistem
  ctx.beginPath();
  ctx.arc(marginX + 24 * s, headerY + headerH / 2, 5 * s, 0, Math.PI * 2);
  ctx.fillStyle = cAccentGreen;
  ctx.fill();

  ctx.fillStyle = cTextPrimary;
  ctx.font = `600 ${14 * s}px Inter, -apple-system, sans-serif`;
  ctx.textBaseline = 'middle';
  ctx.fillText('ENTERPRISE CONFERENCE NETWORK', marginX + 40 * s, headerY + headerH / 2);

  // Badge Protokol Keamanan
  const secX = marginX + 310 * s;
  drawRoundedRect(secX, headerY + 14 * s, 110 * s, 28 * s, 14 * s, '#162238', true, cBorderHighlight, 1 * s);
  ctx.fillStyle = cTextSecondary;
  ctx.font = `500 ${11 * s}px Inter, -apple-system, sans-serif`;
  ctx.fillText('E2E ENCRYPTED', secX + 16 * s, headerY + headerH / 2);

  // Timer Pertemuan Otomatis (loopT)
  const totalSeconds = Math.floor(1240 + loopT);
  const mins = String(Math.floor(totalSeconds / 60)).padStart(2, '0');
  const secs = String(totalSeconds % 60).padStart(2, '0');
  const timeStr = `REC 00:${mins}:${secs}`;
  ctx.fillStyle = '#EF4444';
  ctx.beginPath();
  ctx.arc(width - marginX - 180 * s, headerY + headerH / 2, 4 * s, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = cTextSecondary;
  ctx.font = `600 ${13 * s}px monospace`;
  ctx.fillText(timeStr, width - marginX - 165 * s, headerY + headerH / 2);

  // Status Channel Terhubung
  drawRoundedRect(width - marginX - 90 * s, headerY + 14 * s, 70 * s, 28 * s, 6 * s, '#162238', true, cBorder, 1 * s);
  ctx.fillStyle = cTextPrimary;
  ctx.font = `600 ${12 * s}px Inter, -apple-system, sans-serif`;
  ctx.fillText('4 NODES', width - marginX - 80 * s, headerY + headerH / 2);

  // 3. Tata Letak Fleksibel (Transisi Halus Grid & Dock)
  const leftAreaW = mainW * 0.72;
  const rightAreaX = marginX + leftAreaW + 16 * s;
  const rightAreaW = mainW - leftAreaW - 16 * s;

  // Data 4 Node Video (Semua nama / username dihapus secara total)
  const nodes = [
    { id: 'NODE // 01', type: 'PRIMARY UPLINK', color: '#3B82F6' },
    { id: 'NODE // 02', type: 'DATA ENGINE', color: '#10B981' },
    { id: 'NODE // 03', type: 'SECURITY RELAY', color: '#8B5CF6' },
    { id: 'NODE // 04', type: 'ANALYTICS HUB', color: '#F59E0B' }
  ];

  // Pergantian speaker aktif secara periodik dan natural
  const speakerCycle = Math.floor(loopT / 4) % 4;

  // Posisi Scene 1 (Grid 2x2 Simetris)
  const gap = 14 * s;
  const s1CardW = (leftAreaW - gap) / 2;
  const s1CardH = (mainH - gap) / 2;
  const s1Pos = [
    { x: marginX, y: mainY, w: s1CardW, h: s1CardH },
    { x: marginX + s1CardW + gap, y: mainY, w: s1CardW, h: s1CardH },
    { x: marginX, y: mainY + s1CardH + gap, w: s1CardW, h: s1CardH },
    { x: marginX + s1CardW + gap, y: mainY + s1CardH + gap, w: s1CardW, h: s1CardH }
  ];

  // Posisi Scene 2 (Dock Vertikal Rapi di Bilah Kanan)
  const s2CardGap = 10 * s;
  const s2CardH = (mainH - s2CardGap * 3) / 4;
  const s2Pos = [
    { x: rightAreaX, y: mainY + (s2CardH + s2CardGap) * 0, w: rightAreaW, h: s2CardH },
    { x: rightAreaX, y: mainY + (s2CardH + s2CardGap) * 1, w: rightAreaW, h: s2CardH },
    { x: rightAreaX, y: mainY + (s2CardH + s2CardGap) * 2, w: rightAreaW, h: s2CardH },
    { x: rightAreaX, y: mainY + (s2CardH + s2CardGap) * 3, w: rightAreaW, h: s2CardH }
  ];

  // Render 4 Kartu Node Video
  for (let i = 0; i < 4; i++) {
    const curX = s1Pos[i].x + (s2Pos[i].x - s1Pos[i].x) * morph;
    const curY = s1Pos[i].y + (s2Pos[i].y - s1Pos[i].y) * morph;
    const curW = s1Pos[i].w + (s2Pos[i].w - s1Pos[i].w) * morph;
    const curH = s1Pos[i].h + (s2Pos[i].h - s1Pos[i].h) * morph;

    const isActive = i === speakerCycle;
    const strokeCol = isActive ? cAccentCyan : cBorder;
    const strokeWidth = isActive ? 2 * s : 1 * s;

    // Latar Kartu
    drawRoundedRect(curX, curY, curW, curH, 10 * s, cBgCard, true, strokeCol, strokeWidth);

    // Label Pengenal Node (Anonim & Korporat)
    const pad = 12 * s;
    const labelFontSize = morph > 0.6 ? 11 * s : 13 * s;
    ctx.fillStyle = cTextPrimary;
    ctx.font = `600 ${labelFontSize}px monospace`;
    ctx.textBaseline = 'top';
    ctx.fillText(nodes[i].id, curX + pad, curY + pad);

    if (morph < 0.6) {
      ctx.fillStyle = cTextMuted;
      ctx.font = `500 ${11 * s}px Inter, sans-serif`;
      ctx.fillText(nodes[i].type, curX + pad, curY + pad + 18 * s);
    }

    // Indikator Grafis Simbolik Pusat (Pengganti Foto/Avatar Pribadi)
    const iconR = (morph > 0.6 ? 18 : 28) * s;
    const iconCX = curX + curW / 2;
    const iconCY = curY + curH / 2 - (morph > 0.6 ? 0 : 8 * s);

    ctx.beginPath();
    ctx.arc(iconCX, iconCY, iconR, 0, Math.PI * 2);
    ctx.fillStyle = cBgCardAlt;
    ctx.fill();
    ctx.strokeStyle = nodes[i].color;
    ctx.lineWidth = 1.5 * s;
    ctx.stroke();

    // Vektor Simbol Node Geometris Bersih
    ctx.save();
    ctx.strokeStyle = nodes[i].color;
    ctx.lineWidth = 1.6 * s;
    const coreSize = iconR * 0.45;
    ctx.beginPath();
    ctx.moveTo(iconCX - coreSize, iconCY);
    ctx.lineTo(iconCX, iconCY - coreSize);
    ctx.lineTo(iconCX + coreSize, iconCY);
    ctx.lineTo(iconCX, iconCY + coreSize);
    ctx.closePath();
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(iconCX, iconCY, 2.5 * s, 0, Math.PI * 2);
    ctx.fillStyle = nodes[i].color;
    ctx.fill();
    ctx.restore();

    // Visualizer Frekuensi Audio Bawah Kartu
    const barCount = morph > 0.6 ? 8 : 14;
    const barW = Math.max(2, 3 * s);
    const barGap = 3 * s;
    const waveStartX = curX + pad;
    const waveStartY = curY + curH - pad - 6 * s;

    for (let b = 0; b < barCount; b++) {
      let amp = 0.2;
      if (isActive) {
        amp = 0.3 + 0.65 * Math.abs(Math.sin(t * 9 + i * 2 + b * 0.7));
      } else {
        amp = 0.15 + 0.1 * Math.abs(Math.sin(t * 2 + b * 0.3));
      }
      const bH = Math.max(3 * s, amp * (18 * s));
      const bx = waveStartX + b * (barW + barGap);
      const by = waveStartY - bH;

      ctx.fillStyle = isActive ? cAccentCyan : '#334155';
      drawRoundedRect(bx, by, barW, bH, 1.5 * s, ctx.fillStyle, false);
    }

    // Telemetri Status Koneksi
    const latX = curX + curW - pad - 32 * s;
    const latY = curY + curH - pad - 12 * s;
    ctx.fillStyle = cAccentGreen;
    ctx.beginPath();
    ctx.arc(latX, latY + 4 * s, 3 * s, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = cTextSecondary;
    ctx.font = `500 ${10 * s}px monospace`;
    ctx.fillText('14ms', latX + 7 * s, latY + 5 * s);
  }

  // 4. Panel Scene 1: Automated Event Stream (Tanpa Username / Nama)
  if (morph < 0.98) {
    ctx.save();
    ctx.globalAlpha = Math.max(0, 1 - morph * 1.25);

    drawRoundedRect(rightAreaX, mainY, rightAreaW, mainH, 10 * s, cBgCard, true, cBorder, 1 * s);

    // Header Stream
    const logPad = 16 * s;
    ctx.fillStyle = cTextPrimary;
    ctx.font = `600 ${14 * s}px Inter, sans-serif`;
    ctx.textBaseline = 'top';
    ctx.fillText('SYSTEM EVENT STREAM', rightAreaX + logPad, mainY + logPad);

    // Tab Filter Kategori
    const tabY = mainY + logPad + 28 * s;
    drawRoundedRect(rightAreaX + logPad, tabY, rightAreaW - logPad * 2, 30 * s, 6 * s, '#0C1220', true, cBorder, 1 * s);
    drawRoundedRect(rightAreaX + logPad + 2 * s, tabY + 2 * s, (rightAreaW - logPad * 2) / 2 - 4 * s, 26 * s, 4 * s, '#1E293B', false);
    ctx.fillStyle = cTextPrimary;
    ctx.font = `600 ${11 * s}px Inter, sans-serif`;
    ctx.fillText('NETWORK LOG', rightAreaX + logPad + 20 * s, tabY + 9 * s);
    ctx.fillStyle = cTextMuted;
    ctx.fillText('TELEMETRY', rightAreaX + rightAreaW / 2 + 18 * s, tabY + 9 * s);

    // Daftar Log Sistem Otomatis
    const systemEvents = [
      { cat: 'CLUSTER SYNC', time: '10:41:02', text: 'Telemetry synchronization verified on US-East.', dot: cAccentBlue },
      { cat: 'DEPLOYMENT', time: '10:42:15', text: 'Pipeline deployment charts calibrated.', dot: cAccentGreen },
      { cat: 'SECURITY', time: '10:43:20', text: 'Zero-trust handshake validated across nodes.', dot: '#8B5CF6' },
      { cat: 'METRICS HUB', time: '10:44:08', text: 'Streaming operational analytics to main view.', dot: cAccentAmber }
    ];

    let eventBoxY = tabY + 44 * s;
    for (let m = 0; m < systemEvents.length; m++) {
      const ebH = 76 * s;
      drawRoundedRect(rightAreaX + logPad, eventBoxY, rightAreaW - logPad * 2, ebH, 8 * s, '#141D30', true, cBorder, 1 * s);

      // Titik Status Kategori
      ctx.beginPath();
      ctx.arc(rightAreaX + logPad + 12 * s, eventBoxY + 16 * s, 4 * s, 0, Math.PI * 2);
      ctx.fillStyle = systemEvents[m].dot;
      ctx.fill();

      ctx.fillStyle = cTextPrimary;
      ctx.font = `600 ${12 * s}px monospace`;
      ctx.fillText(systemEvents[m].cat, rightAreaX + logPad + 22 * s, eventBoxY + 10 * s);

      ctx.fillStyle = cTextMuted;
      ctx.font = `500 ${10 * s}px monospace`;
      ctx.fillText(systemEvents[m].time, rightAreaX + rightAreaW - logPad - 46 * s, eventBoxY + 11 * s);

      ctx.fillStyle = cTextSecondary;
      ctx.font = `400 ${11 * s}px Inter, sans-serif`;
      ctx.fillText(systemEvents[m].text, rightAreaX + logPad + 12 * s, eventBoxY + 36 * s);

      eventBoxY += ebH + 10 * s;
    }

    // Bar Status Input Sistem Bawah
    const inBoxH = 40 * s;
    const inBoxY = mainY + mainH - inBoxH - logPad;
    drawRoundedRect(rightAreaX + logPad, inBoxY, rightAreaW - logPad * 2, inBoxH, 6 * s, '#0C1220', true, cBorder, 1 * s);
    ctx.fillStyle = cTextMuted;
    ctx.font = `400 ${11 * s}px Inter, sans-serif`;
    ctx.fillText('Automated command input active...', rightAreaX + logPad + 14 * s, inBoxY + 13 * s);

    ctx.restore();
  }

  // 5. Panel Scene 2: Shared Screen Analytics Dashboard
  if (morph > 0.02) {
    ctx.save();
    ctx.globalAlpha = Math.min(1, morph * 1.2);

    drawRoundedRect(marginX, mainY, leftAreaW, mainH, 10 * s, cBgCard, true, cBorder, 1 * s);

    // Header Screen Share
    const dashPad = 22 * s;
    const headerRowY = mainY + dashPad;
    drawRoundedRect(marginX + dashPad, headerRowY, 110 * s, 26 * s, 4 * s, '#1E293B', true, cBorderHighlight, 1 * s);
    ctx.fillStyle = cAccentCyan;
    ctx.font = `600 ${11 * s}px monospace`;
    ctx.fillText('LIVE STREAM', marginX + dashPad + 16 * s, headerRowY + 7 * s);

    ctx.fillStyle = cTextPrimary;
    ctx.font = `600 ${16 * s}px Inter, sans-serif`;
    ctx.fillText('GLOBAL ARCHITECTURE VELOCITY & PERFORMANCE', marginX + dashPad + 126 * s, headerRowY + 4 * s);

    // Row Metrik Ringkas KPI
    const kpiY = headerRowY + 42 * s;
    const kpiGap = 12 * s;
    const kpiW = (leftAreaW - dashPad * 2 - kpiGap * 2) / 3;
    const kpiH = 84 * s;

    const kpiData = [
      { label: 'CLUSTER THROUGHPUT', val: '98.42%', delta: '+4.8% vs last cycle', color: cAccentGreen },
      { label: 'GLOBAL LATENCY', val: '18.2 ms', delta: 'Nominal operational state', color: cAccentBlue },
      { label: 'COMPLETION RATIO', val: '142 / 150', delta: '94.6% Milestone Target', color: cAccentCyan }
    ];

    for (let k = 0; k < 3; k++) {
      const kx = marginX + dashPad + k * (kpiW + kpiGap);
      drawRoundedRect(kx, kpiY, kpiW, kpiH, 8 * s, '#141D30', true, cBorder, 1 * s);

      ctx.fillStyle = cTextMuted;
      ctx.font = `600 ${10 * s}px Inter, sans-serif`;
      ctx.fillText(kpiData[k].label, kx + 14 * s, kpiY + 12 * s);

      ctx.fillStyle = cTextPrimary;
      ctx.font = `700 ${22 * s}px monospace`;
      ctx.fillText(kpiData[k].val, kx + 14 * s, kpiY + 32 * s);

      ctx.fillStyle = kpiData[k].color;
      ctx.font = `500 ${10 * s}px Inter, sans-serif`;
      ctx.fillText(kpiData[k].delta, kx + 14 * s, kpiY + 62 * s);
    }

    // Area Grafik Vektor Garis dengan Grid Presisi
    const chartY = kpiY + kpiH + 18 * s;
    const chartW = leftAreaW - dashPad * 2;
    const chartH = mainY + mainH - chartY - dashPad;
    drawRoundedRect(marginX + dashPad, chartY, chartW, chartH, 8 * s, '#0C1220', true, cBorder, 1 * s);

    ctx.fillStyle = cTextSecondary;
    ctx.font = `600 ${12 * s}px Inter, sans-serif`;
    ctx.fillText('REAL-TIME SYSTEM PIPELINE LOAD (SLA MONITOR)', marginX + dashPad + 18 * s, chartY + 16 * s);

    const plotLeft = marginX + dashPad + 44 * s;
    const plotRight = marginX + dashPad + chartW - 24 * s;
    const plotTop = chartY + 48 * s;
    const plotBottom = chartY + chartH - 34 * s;
    const plotW = plotRight - plotLeft;
    const plotH = plotBottom - plotTop;

    // Grid Horizontal
    ctx.strokeStyle = '#162238';
    ctx.lineWidth = 1 * s;
    const hDivs = 4;
    for (let d = 0; d <= hDivs; d++) {
      const gy = plotTop + (plotH / hDivs) * d;
      ctx.beginPath();
      ctx.moveTo(plotLeft, gy);
      ctx.lineTo(plotRight, gy);
      ctx.stroke();

      ctx.fillStyle = cTextMuted;
      ctx.font = `500 ${9 * s}px monospace`;
      const valLabel = `${100 - d * 25}%`;
      ctx.fillText(valLabel, plotLeft - 32 * s, gy - 2 * s);
    }

    // Sumbu X Waktu
    const xLabels = ['00:00', '04:00', '08:00', '12:00', '16:00', '20:00', '24:00'];
    for (let xl = 0; xl < xLabels.length; xl++) {
      const lx = plotLeft + (plotW / (xLabels.length - 1)) * xl;
      ctx.fillStyle = cTextMuted;
      ctx.font = `500 ${9 * s}px monospace`;
      ctx.fillText(xLabels[xl], lx - 14 * s, plotBottom + 16 * s);
    }

    // Kurva Data Bezier Presisi & Stabil
    const sampleCount = 9;
    const points = [];
    for (let p = 0; p < sampleCount; p++) {
      const px = plotLeft + (plotW / (sampleCount - 1)) * p;
      const waveVal = Math.sin((p * 0.8) + (t * 0.75)) * 0.22 + Math.cos((p * 1.4) - (t * 0.5)) * 0.15;
      const baseNorm = 0.45 + (p / sampleCount) * 0.25;
      const py = plotBottom - Math.max(0.1, Math.min(0.9, baseNorm + waveVal)) * plotH;
      points.push({ x: px, y: py });
    }

    // Area Gradien di Bawah Garis (Tanpa Efek Glow)
    ctx.beginPath();
    ctx.moveTo(points[0].x, plotBottom);
    ctx.lineTo(points[0].x, points[0].y);
    for (let p = 0; p < points.length - 1; p++) {
      const cpX = (points[p].x + points[p + 1].x) / 2;
      const cpY = (points[p].y + points[p + 1].y) / 2;
      ctx.quadraticCurveTo(points[p].x, points[p].y, cpX, cpY);
    }
    ctx.lineTo(points[points.length - 1].x, points[points.length - 1].y);
    ctx.lineTo(points[points.length - 1].x, plotBottom);
    ctx.closePath();

    const chartAreaGrad = ctx.createLinearGradient(0, plotTop, 0, plotBottom);
    chartAreaGrad.addColorStop(0, 'rgba(37, 99, 235, 0.28)');
    chartAreaGrad.addColorStop(1, 'rgba(37, 99, 235, 0.0)');
    ctx.fillStyle = chartAreaGrad;
    ctx.fill();

    // Garis Utama Kurva Data
    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    for (let p = 0; p < points.length - 1; p++) {
      const cpX = (points[p].x + points[p + 1].x) / 2;
      const cpY = (points[p].y + points[p + 1].y) / 2;
      ctx.quadraticCurveTo(points[p].x, points[p].y, cpX, cpY);
    }
    ctx.lineTo(points[points.length - 1].x, points[points.length - 1].y);
    ctx.strokeStyle = cAccentCyan;
    ctx.lineWidth = 2.5 * s;
    ctx.stroke();

    // Titik Verifikasi Kurva
    for (let p = 0; p < points.length; p++) {
      ctx.beginPath();
      ctx.arc(points[p].x, points[p].y, 3.5 * s, 0, Math.PI * 2);
      ctx.fillStyle = '#0C1220';
      ctx.fill();
      ctx.strokeStyle = cAccentCyan;
      ctx.lineWidth = 2 * s;
      ctx.stroke();
    }

    // Scrubber Garis Telemetri Bergerak
    const scrubIndex = Math.floor((loopT % 8) / 8 * (points.length - 1));
    const activePt = points[scrubIndex] || points[points.length - 2];

    ctx.beginPath();
    ctx.moveTo(activePt.x, plotTop);
    ctx.lineTo(activePt.x, plotBottom);
    ctx.strokeStyle = '#475569';
    ctx.setLineDash([4 * s, 4 * s]);
    ctx.lineWidth = 1 * s;
    ctx.stroke();
    ctx.setLineDash([]);

    // Tooltip Nilai Telemetri
    drawRoundedRect(activePt.x - 36 * s, activePt.y - 30 * s, 72 * s, 22 * s, 4 * s, '#1E293B', true, cAccentCyan, 1 * s);
    ctx.fillStyle = cTextPrimary;
    ctx.font = `600 ${10 * s}px monospace`;
    ctx.fillText('94.8 MB/s', activePt.x - 26 * s, activePt.y - 19 * s);

    ctx.restore();
  }

  // 6. Bar Kontrol Bawah (Floating Control Dock)
  const dockW = 420 * s;
  const dockX = (width - dockW) / 2;
  const dockBtnCount = 6;
  const dockBtnSize = 42 * s;
  const dockBtnSpacing = (dockW - dockBtnSize * dockBtnCount) / (dockBtnCount + 1);

  drawRoundedRect(dockX, footerY, dockW, footerH, 16 * s, '#0E1626', true, cBorder, 1 * s);

  const controls = [
    { type: 'MIC', active: true, color: '#1E293B', fg: cTextPrimary },
    { type: 'CAM', active: true, color: '#1E293B', fg: cTextPrimary },
    { type: 'SHARE', active: currentScene === 1, color: currentScene === 1 ? cAccentBlue : '#1E293B', fg: cTextPrimary },
    { type: 'LOG', active: false, color: '#1E293B', fg: cTextPrimary },
    { type: 'SETTINGS', active: false, color: '#1E293B', fg: cTextPrimary },
